# MantleOS direct afferent nerve: session boundary.
try:
    from mantle.nerves import session_started as _mantle_session_started
    _mantle_session_started(
        session_id=agent.session_id or "",
        model=agent.model or "",
        surface=getattr(agent, "platform", None) or "",
    )
except Exception:
    logger.debug("Mantle session nerve unavailable", exc_info=True)

# MantleOS direct afferent nerve: finalized semantic MIND turn.
if final_response and not interrupted:
    try:
        from mantle.nerves import after_mind as _mantle_after_mind
        _mantle_after_mind(
            user_message=original_user_message,
            assistant_response=final_response,
            session_id=agent.session_id or "",
            turn_id=turn_id,
            surface=getattr(agent, "platform", None) or "",
        )
    except Exception:
        logger.debug("Mantle MIND-result nerve unavailable", exc_info=True)

# MantleOS direct efferent nerve: AppAI Limb proposal.
if block_message is None:
    try:
        from mantle.nerves import authorize_tool as _mantle_authorize_tool
        _mantle_block = _mantle_authorize_tool(
            tool_name=function_name,
            arguments=final_args,
            session_id=getattr(agent, "session_id", "") or "",
            turn_id=getattr(agent, "_current_turn_id", "") or "",
        )
        if _mantle_block:
            block_message = _mantle_block
            block_error_type = "mantle_authority_block"
    except Exception:
        if getattr(agent, "_mantle_addressed", False) is True:
            block_message = "AppAI authority unavailable; addressed motor activity denied"
            block_error_type = "mantle_authority_unavailable"
        logger.debug("Mantle Limb-authority nerve unavailable", exc_info=True)

# MantleOS direct afferent nerve: actual CLI session boundary.
try:
    from mantle.nerves import session_ended as _mantle_session_ended
    _mantle_session_ended(
        session_id=session_id or "",
        surface=platform or "cli",
        reason=reason or "shutdown",
    )
except Exception:
    logger.debug("Mantle CLI session-end nerve unavailable", exc_info=True)

# MantleOS direct afferent nerve: actual gateway session boundary.
_mantle_agent = session.get("agent")
if _mantle_agent is not None:
    try:
        from mantle.nerves import session_ended as _mantle_session_ended
        _mantle_session_ended(
            session_id=getattr(_mantle_agent, "session_id", None)
            or session.get("session_key", ""),
            surface=_session_source(session) or "tui",
            reason=end_reason or "tui_close",
        )
    except Exception:
        logger.debug("Mantle gateway session-end nerve unavailable", exc_info=True)
